using System.Text; namespace InsuranceAutomation.Core; public sealed class ManualTrace { readonly List<(string Step,string Status,string Data)> _rows=new(); public void Add(string s,string st,string data="")=>_rows.Add((s,st,data)); public void Write(string path,string title){Directory.CreateDirectory(Path.GetDirectoryName(path)!);var b=new StringBuilder();b.Append("<html><head><meta charset='utf-8'><style>body{font-family:Arial;margin:24px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ccc;padding:8px}th{background:#eee}.Passed{color:green}.Failed{color:#b00020}</style></head><body><h1>").Append(System.Net.WebUtility.HtmlEncode(title)).Append("</h1><table><tr><th>#</th><th>Manual step</th><th>Status</th><th>Resolved data</th></tr>");int i=1;foreach(var r in _rows)b.Append($"<tr><td>{i++}</td><td>{System.Net.WebUtility.HtmlEncode(r.Step)}</td><td class='{r.Status}'>{r.Status}</td><td>{System.Net.WebUtility.HtmlEncode(r.Data)}</td></tr>");b.Append("</table></body></html>");File.WriteAllText(path,b.ToString());} }
